add('flatness_uncommitted_data','inactive_for_requested_datasets','Five fine-grained datasets and Het5','Flatness git diff utils/data.py contains only optional ImageNet-R dataset_exclude_manifest. It is scoped to iImageNetR and disabled absent path; does not modify sample lists, labels, preprocessing for this table.',[ref(F,'utils/data.py',708)])
