add('temporary_linear_versions','active_rng_side_effect','Shared training LoRA backbone, all seven except CL-LoRA','Flatness, Copy HEAD and Sep18 formal train forward create four temporary random Linear modules unconditionally, even task_id=0. Copy working and Sep16 RNG-controlled code replace historical-factor application with F.linear and remove that CPU RNG consumption. Fixed weights and factors retain same intended forward algebra, but subsequent RNG trajectory is not guaranteed equal.',[ref(F,'backbone/lora.py',174),ref(S,'backbone/lora.py',174),ref(C,'backbone/lora.py',174),ref(R,'backbone/lora.py',174)])
add('eval_class_unmodified','unchanged_scope','Shared LoRA evaluation class','The independent _LoRA_qkv_timm_eval class is unchanged across all five versions and still creates temporary Linear modules. Do not describe working-tree train-forward change as fixing all evaluation RNG consumption.',[ref(F,'backbone/lora.py',229),ref(C,'backbone/lora.py',233)])
add('external_delta','inactive_default','Shared training LoRA','Copy HEAD/formal vs Flatness add external_delta_w_q/v=None and conditional additions. Unset for ordinary methods; optional diagnostic/structured perturbation paths activate only when assigning tensors.',[ref(S,'backbone/lora.py',166),ref(S,'backbone/lora.py',216)])
add('extra_eval_rng','active_extra_traversal','Vanilla SeqLoRA and inheriting EWC/GAM, not independent Inf/OLoRA/SDLoRA/CL learners','Copy HEAD/formal/working SeqLoRA add current-task local accuracy passes every five epochs and at task end versus Flatness. These are not behind optional flag. They traverse loaders and forward modules; with global RNG/default generator and temporary-Linears code they may shift subsequent sampling/augmentation RNG. For persistent workers iterator reuse differs, so do not claim identical base-seed redraw on every reused iteration.',[ref(C,'models_LoRAbasedCL/seqlora.py',437),ref(C,'models_LoRAbasedCL/seqlora.py',1750),ref(C,'models_LoRAbasedCL/seqlora.py',2152),dict(path='/data/115-2/users/liying/conda_storage/envs/Pilot_new/lib/python3.11/site-packages/torch/utils/data/dataloader.py',line=601)])
add('fisher_split','inactive_default','SeqLoRA and inheriting EWC/GAM','Copy adds heldout Fisher split and class-order override support, but with absent/false split parameters and class_order_override absent, training set still uses all current-task examples. ewc_fisher_source default string heldout does not create heldout data: getter falls back to train_loader.',[ref(C,'models_LoRAbasedCL/seqlora.py',215),ref(C,'models_LoRAbasedCL/seqlora.py',341),ref(C,'models_LoRAbasedCL/ewclora_youyue_fitArchitechture.py',135),ref(C,'utils/data_manager.py',384)])
add('min_lr','same_default_different_api','Baseline and GAM schedulers','Flatness Vanilla/Inf/OLoRA/SDLoRA default min_lr=.1*LR. Copy/formal Seq support new ratio/absolute overrides but same default .1*LR. CL directly calls CosineAnnealingLR without eta_min, so min LR is zero. Merely adding min_lr to CL config is ignored by current CL implementation.',[ref(F,'models_LoRAbasedCL/seqlora.py',1341),ref(F,'models_LoRAbasedCL/inflora.py',390),ref(F,'models_LoRAbasedCL/olora.py',194),ref(F,'models_LoRAbasedCL/sdlora.py',230),ref(C,'models_LoRAbasedCL/seqlora.py',288),ref(S,'models_LoRAbasedCL/cllora_aligned.py',68)])
add('worker_real_settings','active_dataset_method_difference','Aircraft especially; all datasets loader route','Seq/EWC/GAM use DataManager.build_dataloader with workers=train_num_workers(default8). Aircraft loader_options set pin_memory=true,persistent_workers=true and DataManager does not read top-level persistent_workers; explicit false JSON alone is ineffective here. Inf/OLoRA/SDLoRA construct DataLoader directly with default pin=false,persistent=false. CL constructs directly workers2,pin=true,persistent=false. Het5 uses own empty loader_options.',[ref(C,'utils/data.py',110),ref(C,'utils/data_manager.py',406),ref(C,'models_LoRAbasedCL/seqlora.py',398),ref(F,'models_LoRAbasedCL/inflora.py',269),ref(F,'models_LoRAbasedCL/olora.py',112),ref(F,'models_LoRAbasedCL/sdlora.py',122),ref(S,'models_LoRAbasedCL/cllora_aligned.py',41)])
add('rng_flags','effective_vs_ignored','EWC/GAM and DataManager','ewc_preserve_fisher_rng read and implemented in Copy/formal, default false. ewc_isolate_clean_rng not read anywhere in Copy working/HEAD/formal GAM learner; Het5 true config therefore ineffective. deterministic_loader_rng/loader_seed not implemented in Copy/formal DataManager. Sep16 rngctl has real implementations for clean isolation and per-loader generators, so differs in actual protocol.',[ref(C,'models_LoRAbasedCL/ewclora_youyue_fitArchitechture.py',89),ref(C,'models_LoRAbasedCL/ewclora_youyue_fitArchitechture.py',338),ref(C,'models_LoRAbasedCL/ewclora_youyue_fitArchitechture_gam.py',494),ref(C,'utils/data_manager.py',417),ref(R,'models_LoRAbasedCL/ewclora_youyue_fitArchitechture_gam.py',39),ref(R,'utils/data_manager.py',428)])
add('seeding_equal','unchanged','Python NumPy Torch seeding','utils/random_reproduce.py and toolkit.py byte-identical across Flatness, Copy, formal, rngctl. set_random seeds Python, NumPy, Torch CPU/CUDA and configures deterministic cuDNN; trainer calls it before DataManager/model creation in both repos. Extra reseeding sites are under disabled linear-probe workflows. Different RNG consumption, not a different initial seed function, is the concern.',[ref(F,'utils/random_reproduce.py',24),ref(F,'src/trainer.py',268),ref(C,'src/trainer.py',910)])
add('trainer_changes','inactive_for_table','Training entrypoint/trainer','Copy main adds local tmpdir and multiprocessing-cleanup handling. Trainer adds opt-in pretrained checkpoint loading, resumed-only evaluation, task0 diagnostics, epoch dynamics, staged checkpoints. Default off / no path in table configs. The normal incremental_train→eval_task→write_metrics→after_task ordering is retained. File diff alone is not evidence of different training updates.',[ref(C,'src/main.py',14),ref(C,'src/trainer.py',976),ref(C,'src/trainer.py',1116),ref(C,'src/trainer.py',1224),ref(C,'src/trainer.py',1263)])
